#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(scales)})
args <- commandArgs(trailingOnly=TRUE); root <- if(length(args)) args[[1]] else getwd(); datadir <- file.path(root,"phase3_publication_figures","data"); outdir <- file.path(root,"phase3_publication_figures")
pr <- read.delim(file.path(datadir,"pr_curves.tsv"),check.names=FALSE); cal <- read.delim(file.path(datadir,"calibration.tsv"),check.names=FALSE); forest <- read.delim(file.path(datadir,"bootstrap_forest.tsv"),check.names=FALSE); attr <- read.delim(file.path(datadir,"attrition.tsv"),check.names=FALSE)
pal <- c("A. thaliana"="#4C78A8","O. sativa"="#F28E2B","A. lyrata"="#59A14F"); theme_pub <- theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),plot.title=element_text(face="bold"),legend.position="bottom",strip.background=element_blank())
p1 <- ggplot(pr,aes(recall,precision,color=species))+geom_line(linewidth=.9)+scale_color_manual(values=pal)+coord_cartesian(xlim=c(0,1),ylim=c(0,1))+labs(title="A  Held-out precision-recall",x="Recall",y="Precision",color=NULL)+theme_pub
cal <- cal[cal$count>0,]; p2 <- ggplot(cal,aes(mean_probability,observed_fraction,color=species))+geom_abline(slope=1,intercept=0,linetype=2,color="grey55")+geom_point(aes(size=count),alpha=.85)+geom_line(aes(group=species),linewidth=.7)+scale_color_manual(values=pal)+scale_size_area(max_size=7)+coord_equal(xlim=c(0,1),ylim=c(0,1))+labs(title="B  Held-out calibration",x="Mean predicted probability",y="Observed fraction",color=NULL,size="Bin count")+theme_pub
forest$group <- interaction(forest$species,forest$tier); p3 <- ggplot(forest,aes(median,species,color=tier))+geom_errorbarh(aes(xmin=lower,xmax=upper),height=.2,position=position_dodge(width=.45),linewidth=.8)+geom_point(position=position_dodge(width=.45),size=2.5)+scale_color_manual(values=c("Sensitive"="#4C78A8","Strict core"="#E15759"))+labs(title="C  Chromosome-bootstrap uncertainty",x="F1 at >=1 bp (95% interval)",y=NULL,color=NULL)+theme_pub
attr$stage <- factor(attr$stage,levels=c("Sensitive","Miniprot-supported","Strict core","Subtype candidates")); p4 <- ggplot(attr,aes(stage,fraction_of_sensitive,color=species,group=species))+geom_line(linewidth=.9)+geom_point(size=2.7)+scale_color_manual(values=pal)+scale_y_continuous(labels=percent_format(accuracy=1),limits=c(0,1))+labs(title="D  Evidence attrition",x=NULL,y="Fraction of sensitive catalog",color=NULL)+theme_pub+theme(axis.text.x=element_text(angle=25,hjust=1))
fig <- (p1|p2)/(p3|p4)+plot_layout(guides="collect")
ggsave(file.path(outdir,"phase3_supplementary_audit.png"),fig,width=12,height=8,dpi=500,bg="white");ggsave(file.path(outdir,"phase3_supplementary_audit.pdf"),fig,width=12,height=8,useDingbats=FALSE);ggsave(file.path(outdir,"phase3_supplementary_audit.svg"),fig,width=12,height=8)
